		addr   ServerAddress
		logs   LogStore
		stable StableStore
		snaps  SnapshotStore
		cfg    Config
	}
	states := make([]nodeState, len(c.rafts))
	for i, r := range c.rafts {
		states[i] = nodeState{
			addr:   r.localAddr,
			logs:   r.logs,
			stable: r.stable,
			snaps:  r.snapshots,
			cfg:    r.config(),
		}
		require.NoError(t, r.Shutdown().Error())
	}

	trans := make([]*InmemTransport, len(states))
	for i := range states {
		_, trans[i] = NewInmemTransport(states[i].addr)
	}
	for i := range trans {
		for j := range trans {
			if i != j {
				trans[i].Connect(states[j].addr, trans[j])
			}
		}
	}

	for i := range states {
		s := states[i]
